const students = $input.all().map(item => item.json);

// Calculate student status summary
const total = students.length;

const completed = students.filter(
  s => s.Status === "Completed"
).length;

const inProgress = students.filter(
  s => s.Status === "In Progress"
).length;

const pending = students.filter(
  s => s.Status === "Pending"
).length;

// Escape spreadsheet values for safe HTML
const esc = value => String(value ?? "")
  .replace(/&/g, "&amp;")
  .replace(/</g, "&lt;")
  .replace(/>/g, "&gt;")
  .replace(/"/g, "&quot;")
  .replace(/'/g, "&#39;");

// Generate HTML table rows
const rows = students.map(s => {

  let color = "#333333";

  if (s.Status === "Completed") {
    color = "#15803d";
  } else if (s.Status === "In Progress") {
    color = "#d97706";
  } else if (s.Status === "Pending") {
    color = "#dc2626";
  }

  return `
    <tr>
      <td>${esc(s.Student_ID)}</td>
      <td>${esc(s.Name)}</td>
      <td>${esc(s.Course)}</td>
      <td style="color:${color};font-weight:bold;">
        ${esc(s.Status)}
      </td>
    </tr>
  `;
}).join("");

// Generate email subject
const subject = "CAIE - Student Course Status Report";

// Generate HTML email body
const body = `
<div style="font-family:Arial,sans-serif;color:#333;">

  <h2 style="color:#1e3a8a;">
    CAIE Student Course Status Report
  </h2>

  <p>Hi,</p>

  <p>Please find the latest student course status
  report from Google Sheets.</p>

  <h3>Student Summary</h3>

  <ul>
    <li>Total Students: ${total}</li>
    <li>Completed: ${completed}</li>
    <li>In Progress: ${inProgress}</li>
    <li>Pending: ${pending}</li>
  </ul>

  <table border="1" cellpadding="10" cellspacing="0"
    style="border-collapse:collapse;width:100%;">

    <tr style="background-color:#1e3a8a;color:white;">
      <th>Student ID</th>
      <th>Name</th>
      <th>Course</th>
      <th>Status</th>
    </tr>

    ${rows}

  </table>

  <p>Regards,<br>
  <b>CAIE Automation Bot</b></p>

  <hr>

  <p style="font-size:12px;color:gray;">
    This email was automatically generated using
    n8n and Google Sheets.
  </p>

</div>
`;

// Return one consolidated email
return [
  {
    json: {
      subject: subject,
      body: body,
      total_students: total,
      completed: completed,
      in_progress: inProgress,
      pending: pending
    }
  }
];
